// Verify the repaired passive pagehide guard with actual independent tabs and pagehide.
import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
import {createHash} from 'node:crypto';
import {execFileSync} from 'node:child_process';
import {mkdir,mkdtemp,readFile,writeFile,symlink} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {join,resolve} from 'node:path';
import {staticOrigin} from './static-origin.mjs';
import {inventory} from '../../scripts/build-pages-artifact.mjs';
assert.equal(process.env.GITHUB_ACTIONS,'true','Only the authorized Linux Actions origin');
const require=createRequire(import.meta.url),{chromium}=require(process.env.PLAYWRIGHT_PACKAGE),git=(...a)=>execFileSync('git',a),sha=b=>createHash('sha256').update(b).digest('hex');
const artifact=resolve(process.env.PAGES_ARTIFACT),reportDir=resolve(process.env.BROWSER_REPORT);await mkdir(reportDir,{recursive:true});
const report={head:process.env.TESTED_HEAD,base:process.env.TESTED_BASE,checkout:git('rev-parse','HEAD').toString().trim(),files:{},rows:[],networkRows:[],captures:[],external:[],mutations:[],limits:['Four EN/UR320/1280 Chromium flows with actual independent tabs, DOM input and real navigation pagehide. No synthesized pagehide or app/storage method replacement.','Only anonymous fixture strings in disposable browser storage. No actual candidates, external requests, messages or submissions.','Four additional EN/UR320/1280 flows keep the actual root worker, stop the origin, observe the unchanged offline reload boundary and recover the anonymous draft online. Only first-name field components are captured. No whole-page, all-language, physical-device or screen-reader certificate.']};
assert.equal(report.checkout,git('rev-parse','HEAD').toString().trim());assert.deepEqual(git('show','-s','--format=%P','HEAD').toString().trim().split(' '),[report.base,report.head]);assert.equal(git('rev-parse','HEAD^{tree}').toString().trim(),git('rev-parse',report.head+'^{tree}').toString().trim());
for(const {path:p}of inventory(artifact)){const source=p.startsWith('tools/coordinator/')?'coordinator-demo/'+p.split('/').at(-1):p,b=await readFile(join(artifact,p));assert.deepEqual(b,git('show',report.head+':'+source));report.files[p]={source,bytes:b.length,sha256:sha(b),publishedExact:b.equals(git('show',report.base+':'+source))};}assert.equal(Object.keys(report.files).length,317);assert.equal(Object.values(report.files).filter(x=>x.publishedExact).length,311);
const serveRoot=await mkdtemp(join(tmpdir(),'primserv-two-tab-current-'));await symlink(artifact,join(serveRoot,'kiris-jobs'),'dir');const origin=staticOrigin(serveRoot),base='http://127.0.0.1:4173/kiris-jobs/',key='citronex_screening_application_v17';let browser;
async function stored(page){return page.evaluate(k=>JSON.parse(localStorage.getItem(k)),key);}
async function capture(page,width,lang,stage){await page.evaluate(()=>document.fonts.ready);const field=page.locator('#firstName').locator('..');await field.scrollIntoViewIfNeeded();const dom=await field.evaluate(n=>({text:n.innerText,value:n.querySelector('input').value,focused:document.activeElement===n.querySelector('input'),visible:n.checkVisibility(),fit:n.scrollWidth<=n.clientWidth+1,lang:document.documentElement.lang,pageFits:document.documentElement.scrollWidth<=innerWidth+1}));assert(dom.visible&&dom.fit&&dom.pageFits&&dom.lang===lang);const file=`two-tab-${width}-${lang}-${stage}.png`;await field.screenshot({path:join(reportDir,file)});report.captures.push({file,width,lang,stage,sha256:sha(await readFile(join(reportDir,file))),dom,originalPixels:true});}
async function resume(page){await page.locator('[data-action="resume"]').focus();await page.keyboard.press('Enter');}
async function run(width,lang){
 const ctx=await browser.newContext({viewport:{width,height:1000},serviceWorkers:'block',reducedMotion:'reduce'});ctx.setDefaultTimeout(15000);await ctx.route('**/*',route=>{const r=route.request(),u=new URL(r.url());if(!['GET','HEAD'].includes(r.method())){report.mutations.push({method:r.method(),path:u.pathname,blocked:true});return route.abort();}if(u.origin!==new URL(base).origin){report.external.push({host:u.hostname,path:u.pathname,blocked:true});return route.abort();}return route.continue();});const a=await ctx.newPage(),errors=[];ctx.on('page',p=>p.on('pageerror',e=>errors.push(e.message)));a.on('pageerror',e=>errors.push(e.message));
 try{
  const entry=base+'apply/?lang='+lang;await a.goto(entry);await a.locator('#languageSearch').fill(lang);await a.locator(`[data-language="${lang}"]`).click();await a.locator('[data-recruiter="yana"]').click();await a.locator('#firstName').fill('OLDER FIXTURE');const older=await stored(a);assert.equal(older.data.firstName,'OLDER FIXTURE');assert.equal(typeof older.id,'string');await a.evaluate(()=>localStorage.setItem('two-tab-unrelated','KEEP'));await capture(a,width,lang,'older-a');
  const b=await ctx.newPage();await b.goto(entry);await resume(b);assert.equal(await b.locator('#firstName').inputValue(),'OLDER FIXTURE');await b.locator('#firstName').fill('LATEST FIXTURE');const latest=await stored(b);assert.equal(latest.data.firstName,'LATEST FIXTURE');assert.equal(latest.id,older.id);assert.equal(latest.routeKey,older.routeKey);assert.equal(latest.language,lang);assert.equal(latest.step,1);await capture(b,width,lang,'latest-b');
  // Real navigation fires the older tab's existing pagehide autosave.
  await a.goto('about:blank');const overwritten=await stored(b);assert.equal(overwritten.data.firstName,'LATEST FIXTURE');assert.deepEqual(overwritten,latest);assert.equal(overwritten.id,latest.id);assert.equal(await b.locator('#firstName').inputValue(),'LATEST FIXTURE');assert.equal(await b.evaluate(()=>localStorage.getItem('two-tab-unrelated')),'KEEP');
  const returned=await ctx.newPage();await returned.goto(entry);await resume(returned);assert.equal(await returned.locator('#firstName').inputValue(),'LATEST FIXTURE');await capture(returned,width,lang,'returned-latest');
  await returned.locator('#firstName').fill('EXPLICIT LATER FIXTURE');assert.equal((await stored(b)).data.firstName,'EXPLICIT LATER FIXTURE');assert.equal(await b.locator('#firstName').inputValue(),'LATEST FIXTURE');
  await returned.locator('[data-action="language"]').click();await returned.locator('[data-action="discard"]').focus();await returned.keyboard.press('Enter');assert.equal(await b.evaluate(k=>localStorage.getItem(k),key),null);await b.goto('about:blank');const fresh=await ctx.newPage();await fresh.goto(entry);assert.equal(await fresh.locator('[data-action="resume"]').count(),0);assert.equal(await fresh.evaluate(k=>localStorage.getItem(k),key),null);assert.equal(await fresh.evaluate(()=>localStorage.getItem('two-tab-unrelated')),'KEEP');assert.deepEqual(errors,[]);
  report.rows.push({width,lang,status:'passed',actualTabAPagehideNavigation:true,older,newerPersistedBeforePagehide:latest,persistedAfterOldPagehide:overwritten,newerTabLiveAnswer:'LATEST FIXTURE',returnedSavedAnswer:'LATEST FIXTURE',newerPersistedAnswerPreserved:true,explicitLaterInputStillSaved:true,nativeDiscardNotResurrectedByOlderTab:true,idRouteLanguageStepPreserved:true,unrelatedKeyPreserved:true,noDelivery:true});
 }catch(e){report.failedCase??={width,lang,message:e.message,errors};await a.screenshot({path:join(reportDir,`failure-two-tab-${width}-${lang}.png`)}).catch(()=>{});throw e;}finally{await ctx.close();}
}
async function raw(page){return page.evaluate(k=>localStorage.getItem(k),key);}
async function cacheKeys(page){return page.evaluate(async()=>{const result=[];for(const name of await caches.keys()){const c=await caches.open(name);for(const r of await c.keys())result.push({name,url:r.url});}return result;});}
async function captureNetwork(page,width,lang,stage){
 await page.evaluate(()=>document.fonts.ready);const field=page.locator('#firstName').locator('..');await field.scrollIntoViewIfNeeded();
 const dom=await field.evaluate(n=>({text:n.innerText,value:n.querySelector('input').value,visible:n.checkVisibility(),fit:n.scrollWidth<=n.clientWidth+1,lang:document.documentElement.lang,pageFits:document.documentElement.scrollWidth<=innerWidth+1}));assert(dom.visible&&dom.fit&&dom.pageFits&&dom.lang===lang);
 const file=`network-${width}-${lang}-${stage}.png`;await field.screenshot({path:join(reportDir,file)});const bytes=await readFile(join(reportDir,file));report.captures.push({file,width,lang,stage,sha256:sha(bytes),dom,originalPixels:true});
}
async function unavailable(page,operation){let error;try{await operation();}catch(e){error=e.message;}assert(error&&/ERR_|net::/i.test(error),`Navigation unexpectedly succeeded: ${error}`);assert.equal(await page.locator('#candidateForm').count(),0);return error;}
async function runNetwork(width,lang){
 const ctx=await browser.newContext({viewport:{width,height:1000},serviceWorkers:'allow',reducedMotion:'reduce'});ctx.setDefaultTimeout(20000);
 await ctx.route('**/*',route=>{const r=route.request(),u=new URL(r.url());if(!['GET','HEAD'].includes(r.method())){report.mutations.push({width,lang,method:r.method(),url:r.url(),path:u.pathname,blocked:true});return route.abort();}if(u.origin!==new URL(base).origin){report.external.push({width,lang,host:u.hostname,path:u.pathname,blocked:true});return route.abort();}return route.continue();});
 const page=await ctx.newPage(),errors=[];page.on('pageerror',e=>errors.push(e.message));let witness;
 try{
  await origin.start();await page.goto(base);await page.evaluate(async()=>{await navigator.serviceWorker.ready;});await page.waitForFunction(()=>!!navigator.serviceWorker.controller);
  const entry=base+`apply/?lang=${lang}&recruiter=yana&location=siechnice`;await page.goto(entry);assert(await page.evaluate(()=>navigator.serviceWorker.controller.scriptURL.endsWith('/kiris-jobs/sw.js')));
  await page.locator('#languageSearch').fill(lang);await page.locator(`[data-language="${lang}"]`).click();await page.locator('[data-recruiter="yana"]').click();await page.locator('#firstName').fill('ONLINE FIXTURE');
  witness=await ctx.newPage();await witness.goto(base+'privacy.html');await witness.evaluate(()=>localStorage.setItem('network-boundary-unrelated','KEEP'));
  const before=JSON.parse(await raw(witness));assert.equal(before.data.firstName,'ONLINE FIXTURE');assert.equal(typeof before.id,'string');assert(before.id.length>0);const beforeKeys=await cacheKeys(witness);assert(beforeKeys.some(r=>r.url===base||r.url===base+'index.html'));assert.deepEqual(beforeKeys.filter(r=>new URL(r.url).pathname.includes('/apply/')),[]);
  await origin.stop();await assert.rejects(fetch(base));await ctx.setOffline(true);
  const input=page.locator('#firstName');await input.focus();await page.keyboard.press('Control+A');await page.keyboard.insertText('OFFLINE FIXTURE');assert.equal(await input.inputValue(),'OFFLINE FIXTURE');assert.equal(await page.evaluate(()=>document.activeElement.id),'firstName');
  const offline=JSON.parse(await raw(witness));assert.equal(offline.data.firstName,'OFFLINE FIXTURE');assert.equal(offline.id,before.id);await captureNetwork(page,width,lang,'offline-open');
  await page.locator('.form-link > summary').click();const publicUrl=new URL(await page.locator('#publicFormUrl').inputValue());assert.equal(publicUrl.origin,'https://oleksandrkiris.github.io');assert.equal(publicUrl.pathname,'/kiris-jobs/apply/');assert.deepEqual([...publicUrl.searchParams],[['lang',lang],['recruiter','yana'],['location','siechnice']]);
  await page.locator('#publicFormLocation').selectOption('bogatynia');const variant=new URL(await page.locator('#publicFormUrl').inputValue());assert.equal(variant.searchParams.get('location'),'bogatynia');assert.equal(await raw(witness),JSON.stringify(offline));
  const queryPage=await ctx.newPage();const queryError=await unavailable(queryPage,()=>queryPage.goto(base+'apply/'+variant.search));await queryPage.close();
  const reloadError=await unavailable(page,()=>page.reload());const retained=JSON.parse(await raw(witness));assert.deepEqual(retained.data,offline.data);assert.equal(retained.id,offline.id);assert.equal(await witness.evaluate(()=>localStorage.getItem('network-boundary-unrelated')),'KEEP');
  const afterKeys=await cacheKeys(witness);assert.deepEqual(afterKeys.filter(r=>new URL(r.url).pathname.includes('/apply/')),[]);
  await ctx.setOffline(false);await origin.start();await page.goto(entry);assert.equal(await page.locator('[data-action="resume"]').count(),1);await page.locator('[data-action="resume"]').focus();await page.keyboard.press('Enter');assert.equal(await input.inputValue(),'OFFLINE FIXTURE');assert.equal(await page.locator('#candidateForm').count(),1);assert.deepEqual(JSON.parse(await raw(witness)).data,offline.data);await captureNetwork(page,width,lang,'online-recovered');assert.deepEqual(errors,[]);
  report.networkRows.push({width,lang,status:'passed',rootWorkerControlled:true,cacheWasNotSeeded:true,beforeKeys,afterKeys,originReallyStopped:true,openFormOfflineEditingAndFocus:true,publicLinkGeneratedOfflineWithoutAnswers:true,exactReloadUnavailable:reloadError,queryEntryUnavailable:queryError,anonymousDraftPreserved:true,unrelatedKeyPreserved:true,onlineRecoveryWithNativeResume:true,noDelivery:true});
 }catch(e){report.failedCase??={width,lang,message:e.message,errors};await page.screenshot({path:join(reportDir,`failure-network-${width}-${lang}.png`)}).catch(()=>{});throw e;}finally{await ctx.setOffline(false);await ctx.close();await origin.stop();}
}
try{await origin.start();browser=await chromium.launch({headless:true});report.browser=browser.version();for(const width of [320,1280])for(const lang of ['en','ur'])await run(width,lang);await origin.stop();for(const width of [320,1280])for(const lang of ['en','ur'])await runNetwork(width,lang);assert.equal(report.rows.length,4);assert.equal(report.networkRows.length,4);assert.equal(report.captures.length,20);assert.deepEqual(report.mutations.filter(r=>!r.blocked||r.method!=='POST'||r.url!=='https://candidate-form-flow.lovable.app/api/public/funnel'),[]);assert.equal(report.mutations.length,4);assert.equal(report.external.length,4);assert(report.external.every(r=>r.blocked&&r.host==='candidate-form-flow.lovable.app'&&r.path==='/api/public/vacancies'));report.blockedCatalogueBootstrapPosts=4;report.applicationDeliveryAttempts=0;report.status='PASSED_4_TWO_TAB_PASSIVE_PAGEHIDE_GUARDS_AND_4_ACTUAL_NETWORK_TRANSITIONS';}catch(e){report.status='FAILED';report.failure=e.stack;throw e;}finally{await browser?.close();await origin.stop();await writeFile(join(reportDir,'acceptance.json'),JSON.stringify(report,null,2)+'\n');}
